values.value:
{
  "contextIds": {
    "selectionObjectType": "User",
    "fieldPath": "ContactId",
    "selectionClause": "Id = :userId"
  },
  "chunkSize": 75,
  "schedulables": [
    {
      "objectType": "sirenum__Timesheet__c",
      "startFieldPath": "sirenum__Week_Ending__c",
      "selectionClause": "sirenum__Worker__c IN :contextIds",
      "icon": {
        "literal": "sirenum:timesheet"
      },
      "variant": {
        "literal": "#330c2f"
      },
      "tuples": [
        {
          "name": "period",
          "icon": {
            "literal": "date_input"
          },
          "value": {
            "field": "sirenum__Week__c"
          }
        },
        {
          "name": "total-pay",
          "icon": {
            "literal": "money"
          },
          "label": {
            "label": {
              "default": "Total Pay",
              "de": "Gesamtvergütung",
              "es": "Pago total",
              "nl": "Totaal uitbetaald",
              "fr": "Rémunération totale",
              "it": "Retribuzione totale"
            }
          },
          "value": {
            "field": "sirenum__Worker_Bill__c"
          }
        },
        {
          "name": "total-shift-pay",
          "icon": {
            "literal": "money"
          },
          "label": {
            "label": {
              "default": "Total Shift Pay",
              "de": "Zahlung Gesamtschicht",
              "es": "Pago total del turno",
              "nl": "Totaal uitbetaald voor de dienst",
              "fr": "Rémunération totale de la mission",
              "it": "Retribuzione del turno totale"
            }
          },
          "value": {
            "field": "sirenum__Total_Pay__c"
          }
        },
        {
          "name": "total-hours",
          "icon": {
            "literal": "clock"
          },
          "value": {
            "field": "sirenum__Total_Hours__c"
          }
        },
        {
          "name": "site",
          "icon": {
            "literal": "home"
          },
          "value": {
            "field": "sirenum__Site__c"
          }
        },
        {
          "name": "job-type",
          "icon": {
            "literal": "picklist"
          },
          "value": {
            "field": "sirenum__Team__r.sirenum__Job_Type__c"
          }
        },
        {
          "name": "client",
          "icon": {
            "literal": "company"
          },
          "value": {
            "field": "sirenum__Team__r.sirenum__Account__r.sirenum__Client__c"
          }
        },
        {
          "name": "taxed-expenses",
          "icon": {
            "literal": "up"
          },
          "value": {
            "field": "sirenum__Taxed_Expenses__c"
          }
        },
        {
          "name": "non-taxed-expenses",
          "icon": {
            "literal": "up"
          },
          "value": {
            "field": "sirenum__Non_Taxed_Expenses__c"
          }
        },
        {
          "name": "taxed-deductions",
          "icon": {
            "literal": "down"
          },
          "value": {
            "field": "sirenum__Taxed_Deductions__c"
          }
        },
        {
          "name": "non-taxed-deductions",
          "icon": {
            "literal": "down"
          },
          "value": {
            "field": "sirenum__Non_Taxed_Deductions__c"
          }
        },
        {
          "name": "bonus",
          "icon": {
            "literal": "topic"
          },
          "value": {
            "field": "sirenum__Bonus__c"
          }
        },
        {
          "name": "loan-repayment",
          "icon": {
            "literal": "down"
          },
          "value": {
            "field": "sirenum__Loan_Repayment_Amount__c"
          }
        },
        {
          "name": "show-breakdown",
          "icon": {
            "literal": "list"
          },
          "label": {
            "label": {
              "default": "Show Pay Details",
              "de": "Zahlungsdetails anzeigen",
              "es": "Mostrar detalle de pago",
              "nl": "Toon de details van de uitbetaling",
              "fr": "Afficher les détails de la rémunération",
              "it": "Mostra dettagli pagamento"
            }
          },
          "uri": {
            "pattern": {
              "format": {
                "default": "$page:embedded/timesheet?id={0}"
              },
              "values": [
                {
                  "field": "Id"
                }
              ]
            }
          }
        },
        {
          "name": "whatsapp",
          "selector": {
            "field": "sirenum__Team__r.sirenum__Timesheet_Supervisor__r.MobilePhone",
            "operator": "IsNull",
            "value": "false"
          },
          "icon": {
            "literal": "sirenum:whatsapp"
          },
          "value": {
            "label": {
              "default": "WhatsApp"
            }
          },
          "uri": {
            "pattern": {
              "format": {
                "default": "https://wa.me/{0}?text=Timesheet {1}-{2} for {3}"
              },
              "values": [
                {
                  "field": "sirenum__Team__r.sirenum__Timesheet_Supervisor__r.MobilePhone",
                  "facet": "display"
                },
                {
                  "field": "sirenum__Week__r.sirenum__Start_Date__c",
                  "facet": "display"
                },
                {
                  "field": "sirenum__Week__r.sirenum__Week_Ending__c",
                  "facet": "display"
                },
                {
                  "field": "sirenum__Team__r.sirenum__Account__r.sirenum__Client__r.Name",
                  "facet": "display"
                }
              ]
            }
          }
        },
        {
          "name": "call",
          "selector": {
            "field": "sirenum__Team__r.sirenum__Timesheet_Supervisor__r.Phone",
            "operator": "IsNull",
            "value": "false"
          },
          "icon": {
            "literal": "call"
          },
          "value": {
            "label": {
              "default": "Call",
              "de": "Anruf",
              "es": "Llamada",
              "nl": "Oproep",
              "fr": "Appel",
              "it": "Chiamata"
            }
          },
          "uri": {
            "pattern": {
              "format": {
                "default": "tel:+{0}"
              },
              "values": [
                {
                  "field": "sirenum__Team__r.sirenum__Timesheet_Supervisor__r.Phone"
                }
              ]
            }
          }
        },
        {
          "name": "email",
          "selector": {
            "field": "sirenum__Team__r.sirenum__Timesheet_Supervisor__r.Email",
            "operator": "IsNull",
            "value": "false"
          },
          "icon": {
            "literal": "email"
          },
          "value": {
            "label": {
              "default": "Email",
              "de": "E-Mail",
              "es": "Correo electrónico",
              "nl": "E‑mail",
              "fr": "Envoyer un e-mail",
              "it": "E-mail"
            }
          },
          "uri": {
            "pattern": {
              "format": {
                "default": "mailto:{0}?subject=Timesheet {1}"
              },
              "values": [
                {
                  "field": "sirenum__Team__r.sirenum__Timesheet_Supervisor__r.Email",
                  "facet": "display"
                },
                {
                  "field": "Name",
                  "facet": "display"
                }
              ]
            }
          }
        }
      ],
      "tileLayouts": [
        {
          "decorations": [
          ],
          "contents": [
            "client",
            "total-pay",
            "total-hours"
          ]
        }
      ],
      "detailLayouts": [
        {
          "decorations": [
            "whatsapp",
            "call",
            "email"
          ],
          "contents": [
            "period",
            "total-pay",
            "total-hours",
            "client",
            "site",
            "job-type",
            "total-shift-pay",
            "bonus",
            "non-taxed-expenses",
            "taxed-expenses",
            "non-taxed-deductions",
            "taxed-deductions",
            "loan-repayment",
            "show-breakdown"
          ]
        }
      ]
    },
    {
      "objectType": "sirenum__Expense__c",
      "startFieldPath": "sirenum__Date_of_expense__c",
      "selectionClause": "sirenum__Contact__c IN :contextIds",
      "relatedLists": [
        {
          "relationship": "Attachments",
          "fields": [
            {
              "path": "CreatedDate"
            },
            {
              "path": "ContentType"
            },
            {
              "path": "Name"
            },
            {
              "path": "OwnerId"
            }
          ],
          "orderByClause": "CreatedDate DESC",
          "limitSize": 10
        }
      ],
      "icon": {
        "literal": "sirenum:expense"
      },
      "variant": {
        "literal": "#9b4258"
      },
      "tuples": [
        {
          "name": "approved",
          "selector": {
            "field": "sirenum__Approved_for_Payment__c",
            "operator": "Equals",
            "value": "true"
          },
          "icon": {
            "literal": "success"
          },
          "value": {
            "label": {
              "default": "Approved",
              "de": "Genehmigt",
              "es": "Aprobado",
              "nl": "Goedgekeurd",
              "fr": "Approuvé",
              "it": "Approvato"
            }
          },
          "variant": {
            "literal": "success"
          }
        },
        {
          "name": "pending",
          "selector": {
            "field": "sirenum__Approved_for_Payment__c",
            "operator": "Equals",
            "value": "false"
          },
          "icon": {
            "literal": "spinner"
          },
          "value": {
            "label": {
              "default": "Pending",
              "de": "Anstehend",
              "es": "Pendiente",
              "nl": "In behandeling",
              "fr": "En attente",
              "it": "In attesa di"
            }
          },
          "variant": {
            "literal": "warning"
          }
        },
        {
          "name": "amount",
          "icon": {
            "literal": "money"
          },
          "value": {
            "field": "sirenum__Amount__c"
          }
        },
        {
          "name": "category",
          "icon": {
            "literal": "standard:category"
          },
          "label": {
            "label": {
              "default": "Type",
              "de": "Typ",
              "es": "Categoría",
              "nl": "Type",
              "fr": "Type",
              "it": "Genere"
            }
          },
          "value": {
            "field": "sirenum__Expense_assigned_to__c"
          }
        },
        {
          "name": "vat-included",
          "icon": {
            "literal": "price_book_entries"
          },
          "value": {
            "field": "sirenum__VAT_Included__c"
          }
        },
        {
          "name": "billable",
          "icon": {
            "literal": "forward_up"
          },
          "label": {
            "label": {
              "default": "Billable",
              "de": "Gebührenpflichtig",
              "es": "Facturable",
              "nl": "Factureerbaar",
              "fr": "Facturable",
              "it": "Fatturabile"
            }
          },
          "value": {
            "field": "sirenum__Charge_to_client__c"
          }
        },
        {
          "name": "account",
          "icon": {
            "literal": "company"
          },
          "value": {
            "field": "sirenum__Account__r.sirenum__Client__c"
          }
        },
        {
          "name": "expense-date",
          "icon": {
            "literal": "date_time"
          },
          "value": {
            "field": "sirenum__Date_of_expense__c"
          }
        },
        {
          "name": "payment-date",
          "icon": {
            "literal": "date_time"
          },
          "value": {
            "field": "sirenum__Date_of_payment__c"
          }
        },
        {
          "name": "comment",
          "icon": {
            "literal": "note"
          },
          "value": {
            "field": "sirenum__Comments__c"
          }
        },
        {
          "name": "supplier",
          "icon": {
            "literal": "store"
          },
          "value": {
            "field": "sirenum__Beneficiary_Name__c"
          }
        },
        {
          "name": "expense-number",
          "icon": {
            "literal": "clock"
          },
          "value": {
            "field": "sirenum__Expense_number__c"
          }
        },
        {
          "name": "attach-photo",
          "selector": {
            "every": {
              "operands": [
                {
                  "field": "sirenum__Approved__c",
                  "operator": "Equals",
                  "value": "false"
                },
                {
                  "field": "sirenum__Approved_for_Payment__c",
                  "operator": "Equals",
                  "value": "false"
                }
              ]
            },
            "operator": "Equals",
            "value": "true"
          },
          "icon": {
            "literal": "photo"
          },
          "label": {
            "label": {
              "default": "Attach Photo",
              "de": "Foto anfügen",
              "es": "Adjuntar Foto",
              "nl": "Foto bijvoegen",
              "fr": "Joindre une photo",
              "it": "Allega Foto"
            }
          },
          "uri": {
            "literal": "$attach:photo"
          }
        },
        {
          "name": "attach-image",
          "selector": {
            "every": {
              "operands": [
                {
                  "field": "sirenum__Approved__c",
                  "operator": "Equals",
                  "value": "false"
                },
                {
                  "field": "sirenum__Approved_for_Payment__c",
                  "operator": "Equals",
                  "value": "false"
                }
              ]
            },
            "operator": "Equals",
            "value": "true"
          },
          "icon": {
            "literal": "image"
          },
          "label": {
            "label": {
              "default": "Attach Image",
              "de": "Attach Image",
              "es": "Attach Image",
              "nl": "Attach Image",
              "fr": "Attach Image",
              "it": "Attach Image"
            }
          },
          "uri": {
            "literal": "$attach:image"
          }
        },
        {
          "name": "attach-file",
          "selector": {
            "every": {
              "operands": [
                {
                  "field": "sirenum__Approved__c",
                  "operator": "Equals",
                  "value": "false"
                },
                {
                  "field": "sirenum__Approved_for_Payment__c",
                  "operator": "Equals",
                  "value": "false"
                }
              ]
            },
            "operator": "Equals",
            "value": "true"
          },
          "icon": {
            "literal": "share_file"
          },
          "label": {
            "label": {
              "default": "Attach File",
              "de": "Attach File",
              "es": "Attach File",
              "nl": "Attach File",
              "fr": "Attach File",
              "it": "Attach File"
            }
          },
          "uri": {
            "literal": "$attach:file"
          }
        },
        {
          "name": "show-attachments",
          "selector": {
            "count": {
              "relationship": "Attachments"
            },
            "operator": "Greater",
            "value": "0"
          },
          "icon": {
            "literal": "file"
          },
          "label": {
            "label": {
              "default": "Show Attachments",
              "de": "Show Attachments",
              "es": "Show Attachments",
              "nl": "Show Attachments",
              "fr": "Show Attachments",
              "it": "Show Attachments"
            }
          },
          "uri": {
            "literal": "$attach:list"
          }
        },
        {
          "name": "new-record",
          "label": {
            "label": {
              "default": "Expense"
            }
          },
          "uri": {
            "pattern": {
              "format": {
                "default": "$action:update?sirenum__Contact__c='{0}'"
              },
              "values": [
                {
                  "user": "contactId"
                }
              ]
            }
          }
        }
      ],
      "tileLayouts": [
        {
          "decorations": [
            "approved",
            "pending"
          ],
          "contents": [
            "supplier",
            "account",
            "amount",
            "category"
          ]
        }
      ],
      "detailLayouts": [
        {
          "decorations": [
            "approved",
            "pending"
          ],
          "contents": [
            "supplier",
            "account",
            "amount",
            "category",
            "vat-included",
            "billable",
            "payment-date",
            "comment",
            "attach-photo",
            "attach-image",
            "attach-file",
            "show-attachments"
          ]
        }
      ],
      "editLayouts": [
        {
          "decorations": [
          ],
          "contents": [
            "expense-date",
            "expense-number",
            "supplier",
            "amount",
            "category",
            "vat-included",
            "billable",
            "comment"
          ]
        }
      ],
      "newRecordInitializers": [
        "new-record"
      ]
    }
  ],
  "realTimeActions": [
  ]
}
